import json
from collections import Counter

with open("mcp-agent-ml-research-read_registry-1778876950637.txt") as f:
    outer = json.loads(f.read())

inner = json.loads(outer["result"])
exps = inner["data"]["experiments"]

# 1. RUNNING or PREPARING
print("=== RUNNING / PREPARING ===")
for eid, e in exps.items():
    if e["status"] in ("RUNNING", "PREPARING"):
        hyp = e.get("hypothesis", "N/A")
        print(f"  {eid} | {e['status']} | {hyp}")

# 2. PENDING
print("\n=== PENDING ===")
for eid, e in exps.items():
    if e["status"] == "PENDING":
        print(f"  {eid} | PENDING")

# 3. Status counts
print("\n=== STATUS COUNTS ===")
status_conclusion = Counter()
for eid, e in exps.items():
    s = e["status"]
    c = e.get("conclusion", "")
    if s == "DONE" and c:
        status_conclusion[f"DONE/{c}"] += 1
    elif s == "DONE":
        status_conclusion["DONE/no-conclusion"] += 1
    else:
        status_conclusion[s] += 1
for k, v in sorted(status_conclusion.items()):
    print(f"  {k}: {v}")

# 4. Most recently updated 5
print("\n=== 5 MOST RECENTLY UPDATED ===")
sorted_exps = sorted(exps.items(), key=lambda x: x[1].get("updated_at", ""), reverse=True)
for eid, e in sorted_exps[:5]:
    print(f"  {eid} | {e['status']} | conclusion={e.get('conclusion','N/A')} | updated_at={e.get('updated_at','N/A')}")

# 5. Experiments with cron or PID
print("\n=== CRON / PID ===")
for eid, e in exps.items():
    spec = e.get("spec", {}) or {}
    pid = spec.get("pid")
    cron = spec.get("cron_id") or spec.get("cron")
    has_cron = any(k for k in spec if "cron" in str(k).lower())
    has_pid = pid is not None
    if has_cron or has_pid:
        print(f"  {eid} | status={e['status']} | pid={pid} | cron_fields={[k for k in spec if 'cron' in str(k).lower()]}")

# Also check top-level fields for cron
for eid, e in exps.items():
    for k in e:
        if "cron" in str(k).lower() or "pid" in str(k).lower():
            if k not in ("spec",):
                print(f"  {eid} top-level field: {k}={e[k]}")

